public static int jahreBisZiel(int gold, int ziel) {
    int jahre = 0;
    while (gold < ziel) {
        gold = gold + gold / 10;
        jahre++;
    }
    return jahre;
}

public static int anzahlInBereich(int[] r, int lo, int hi) {
    int anzahl = 0;
    for (int i = 0; i < r.length; i++) {
        if (r[i] >= lo && r[i] <= hi) {
            anzahl++;
        }
    }
    return anzahl;
}

